template <class T>
class numeric_limits {
public:
    static constexpr T min() noexcept;  // For floating-point types, returns the minimum positive normalized value if denormalization is supported; implementation notes: Compiler specializes this for float/double using IEEE 754 constants, resolved at compile-time via constexpr.
    static constexpr T max() noexcept;  // Returns the maximum finite value; for unsigned types, it's the largest representable value; implementation notes: Evaluated at compile-time, often inlined as a constant load in assembly.
};
